49	  vec3 c = mix(dark, mid, 0.25 + 0.75 * body);
50	  c = mix(c, gold, 0.55 * exp(-pow((v - 0.50) / 0.22, 2.0)));
51	  float lip = exp(-pow((v - 0.12) / 0.028, 2.0)) + exp(-pow((v - 0.88) / 0.028, 2.0));
52	  float groove = exp(-pow((v - 0.20) / 0.016, 2.0)) + exp(-pow((v - 0.80) / 0.016, 2.0)) + 0.6 * exp(-pow((v - 0.36) / 0.012, 2.0)) + 0.6 * exp(-pow((v - 0.64) / 0.012, 2.0));
