71	const WALL_GLSL = /* glsl */ `
72	vec3 e30Wall(vec2 q, vec3 n, vec3 V, vec3 T) {
73	  vec3 n2 = dot(n, V) < 0.0 ? -n : n;
74	  float fw = dot(reflect(-V, n2), T);
75	  float lit = smoothstep(-0.8, 0.9, fw);
76	  vec3 base = mix(vec3(0.40, 0.15, 0.56), vec3(0.62, 0.30, 0.80), lit);
77	  // brushed grain + broad soft sheen bands running round the drum (world-anchored)
78	  float grain = sin(q.y * 37.0 + sin(q.x * 0.9) * 2.0) * 0.5 + sin(q.y * 71.0 + q.x * 0.31) * 0.5;
79	  base *= 1.0 + 0.035 * grain;
80	  float sh = pow(0.5 + 0.5 * sin(q.x * 0.21 + 0.8), 6.0) * 0.6 + pow(0.5 + 0.5 * sin(q.x * 0.13 - 1.1), 10.0) * 0.5;
81	  base = mix(base, vec3(0.86, 0.62, 0.98), 0.32 * sh * (0.5 + 0.5 * lit));
82	  base += vec3(0.95, 0.70, 1.0) * 0.20 * pow(max(fw, 0.0), 10.0);
83	  // slots: rows round the drum (long axis round it), staggered; arc pitch 0.80 u, row pitch 0.56 u, slot 0.40 x 0.13 u
84	  vec2 pitch = vec2(0.80, 0.56);
85	  float row = floor(q.y / pitch.y);
86	  vec2 p = vec2((fract(q.x / pitch.x + 0.5 * mod(row, 2.0)) - 0.5) * pitch.x, (fract(q.y / pitch.y) - 0.5) * pitch.y);
