129	export function buildE30Bands(rings: { p: THREE.Vector3; t: THREE.Vector3; r: THREE.Vector3; u: THREE.Vector3; R: number }[], W: number, D: number, NS = 160) {
130	  const h = W / 2;
131	  const prof: [number, number][] = [[0.3, -h], [-0.25 * D, -h], [-0.85 * D, -h + 0.1], [-D, -h + 0.25], [-D, -h + 0.45], [-0.86 * D, -h + 0.62]];
132	  for (let k = 1; k < 10; k++) { const f = k / 10; prof.push([-0.86 * D - 0.1 * D * Math.sin(Math.PI * f), -h + 0.62 + f * (W - 1.24)]); }
133	  prof.push([-0.86 * D, h - 0.62], [-D, h - 0.45], [-D, h - 0.25], [-0.85 * D, h - 0.1], [-0.25 * D, h], [0.3, h]);
134	  const vP: number[] = [0];
135	  for (let i = 1; i < prof.length; i++) vP.push(vP[i - 1] + Math.hypot(prof[i][0] - prof[i - 1][0], prof[i][1] - prof[i - 1][1]));
136	  const L = vP[vP.length - 1];
137	  const np = prof.length, pos: number[] = [], tile: number[] = [], ls: number[] = [], idx: number[] = [];
138	  let base = 0;
139	  const dir = new THREE.Vector3();
140	  for (const g of rings) {
141	    for (let i = 0; i <= NS; i++) {
142	      const ph = (i / NS) * Math.PI * 2;
143	      dir.copy(g.r).multiplyScalar(Math.cos(ph)).addScaledVector(g.u, Math.sin(ph));
144	      for (let j = 0; j < np; j++) {
145	        const [x, y] = prof[j];
146	        const p = g.p.clone().addScaledVector(g.t, y).addScaledVector(dir, g.R + x);
147	        pos.push(p.x, p.y, p.z); tile.push(ph, vP[j] / L); ls.push(y, 0);
148	      }
149	    }
150	    for (let i = 0; i < NS; i++) for (let j = 0; j < np - 1; j++) {
151	      const a = base + i * np + j, b = a + 1, c = a + np, d = c + 1;
152	      idx.push(a, c, b, b, c, d);
153	    }
154	    base += (NS + 1) * np;
155	  }
156	  const geo = new THREE.BufferGeometry();
157	  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
158	  geo.setAttribute('aTile', new THREE.Float32BufferAttribute(tile, 2));
159	  geo.setAttribute('aLS', new THREE.Float32BufferAttribute(ls, 2));
