            let best = Infinity, wy = -Infinity;
            for (let k = -14; k <= 8; k += 0.5) {
              const q = this.course.sample(Math.max(0, s + k)).pos, dx = q.x - pv.x, dz = q.z - pv.z;
              if (dx * dx + dz * dz < best) { best = dx * dx + dz * dz; wy = q.y; }
            }
