+  vec2 p = vec2((fract(arc / pitch.x + 0.5 * mod(row, 2.0)) - 0.5) * pitch.x, (fract(ax / pitch.y) - 0.5) * pitch.y);
+  float rr = 0.5 * uSbSlot.w, hl = 0.5 * uSbSlot.z;
