+  const h = W / 2;
+  const prof: [number, number][] = [[0.3, -h], [-0.8 * D, -h], [-D, -h + 0.08], [-D - 0.07, -h + 0.22], [-D - 0.07, -h + 0.42], [-D + 0.05, -h + 0.52], [-D + 0.05, -h + 0.62]];
