+export function makeSbJoin(tube07: THREE.Object3D) {
+  const mats: { fg?: FG; rest: { col: THREE.Color; rng: THREE.Vector3; mid: THREE.Color; mrng: THREE.Vector3 } | null; m: THREE.MeshStandardMaterial; colRest: THREE.Color }[] = [];
